```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = crate::wasi::clocks::wall_clock::now().seconds;
        let body = crate::aap::caps::http_client::get(&feed_url);
        let fetched = body.chars().count() as u32;
        let message = format!("heartbeat at {}: fetched {} characters", seconds, fetched);
        let notified = crate::aap::caps::notifier::notify(&message);
        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
